176	/* Gradientes e efeitos baseados na paleta Pantone da empresa (sem verde oliva) */
177	@layer components {
178	  .pantone-gradient-natural {
179	    background: linear-gradient(135deg, hsl(var(--accent)), hsl(var(--primary)));
180	  }
181	  
182	  .pantone-gradient-terra {
183	    background: linear-gradient(135deg, hsl(var(--primary)), hsl(var(--background) / 0.8));
184	  }
185	  
186	  .pantone-gradient-subtle {
187	    background: linear-gradient(135deg, hsl(var(--background) / 0.1), hsl(var(--primary) / 0.1));
188	  }
189	  
190	  .pantone-accent-line {
191	    border-left: 4px solid hsl(var(--primary));
192	  }
193	  
194	  .pantone-background-pattern {
195	    background: 
196	      radial-gradient(circle at 20% 80%, hsl(var(--primary) / 0.1) 0%, transparent 50%),
197	      radial-gradient(circle at 80% 20%, hsl(var(--accent) / 0.1) 0%, transparent 50%),
198	      hsl(var(--background));
199	  }
200	  
201	  .pantone-glass-effect {
202	    background: hsl(var(--card) / 0.95);
203	    backdrop-filter: blur(12px);
204	    border: 1px solid hsl(var(--border) / 0.4);
205	    border-radius: var(--radius);
206	  }
207	  
208	  .pantone-card {
209	    background: linear-gradient(135deg, 
210	      hsl(var(--card) / 0.9), 
211	      hsl(var(--card) / 0.7));
212	    backdrop-filter: blur(8px);
213	    border-radius: calc(var(--radius) + 4px);
214	    border: 1px solid hsl(var(--border));
215	    position: relative;
216	    overflow: hidden;
217	  }
218	  
219	  .pantone-card::before {
220	    content: '';
221	    position: absolute;
222	    top: 0;
223	    left: 0;
224	    right: 0;
225	    height: 2px;
226	    background: linear-gradient(90deg, 
227	      hsl(var(--primary)), 
228	      hsl(var(--accent)));
229	    border-radius: calc(var(--radius) + 4px) calc(var(--radius) + 4px) 0 0;
230	  }
231	
232	  .pantone-stat-card {
233	    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
234	    transform: translateY(0);
235	    background: hsl(var(--card));
236	    border: 1px solid hsl(var(--border));
237	    border-radius: var(--radius);
238	  }
239	  
240	  .pantone-stat-card:hover {
241	    transform: translateY(-2px);
242	    box-shadow: 0 10px 25px -5px hsl(var(--primary) / 0.15);
243	    border-color: hsl(var(--accent));
244	  }
245	
246	  .pantone-dashboard-grid {
247	    display: grid;
248	    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
249	    gap: 1.5rem;
250	    padding: 1rem;
251	  }
252	
253	  /* Componentes modernos com design Pantone */
254	  .pantone-interface {
255	    background: linear-gradient(145deg, hsl(var(--background)), hsl(var(--muted) / 0.3));
256	    border: 1px solid hsl(var(--border));
257	    backdrop-filter: blur(8px);
258	    border-radius: var(--radius);
259	  }
260	
261	  .pantone-input-area {
262	    background: hsl(var(--card));
263	    border: 2px solid hsl(var(--border));
264	    border-radius: var(--radius);
265	    transition: all 0.3s ease;
266	    position: relative;
267	    overflow: hidden;
268	  }
269	
270	  .pantone-input-area:focus-within {
271	    border-color: hsl(var(--primary));
272	    box-shadow: 0 0 0 3px hsl(var(--primary) / 0.1);
273	  }
274	
275	  .pantone-input-area::before {
276	    position: absolute;
277	    top: 0;
278	    left: -100%;
279	    width: 100%;
280	    height: 2px;
281	    background: hsl(var(--primary));
282	    transition: left 0.6s ease;
283	  }
284	
285	  .ai-input-area:focus-within::before {
286	    left: 0;
287	  }
288	
289	  .ai-button {
290	    background: linear-gradient(135deg, hsl(var(--primary)), hsl(var(--momma-primary-dark)));
291	    border: none;
292	    transition: all 0.3s ease;
293	    position: relative;
294	    overflow: hidden;
295	  }
296	
297	  .ai-button:hover {
298	    transform: translateY(-1px);
299	    box-shadow: 0 8px 25px hsl(var(--primary) / 0.3);
300	  }
301	
302	  .ai-button:disabled {
303	    background: hsl(var(--muted));
304	    transform: none;
305	    box-shadow: none;
306	  }
307	
308	  .ai-result-card {
309	    background: hsl(var(--card));
310	    border: 1px solid hsl(var(--border));
311	    border-radius: 12px;
312	    transition: all 0.3s ease;
313	    position: relative;
314	    overflow: hidden;
315	  }
316	
317	  .ai-result-card::before {
318	    content: '';
319	    position: absolute;
320	    top: 0;
321	    left: 0;
322	    right: 0;
323	    height: 3px;
324	    background: linear-gradient(90deg, hsl(var(--momma-gradient-start)), hsl(var(--momma-gradient-end)));
325	  }
326	
327	  .ai-result-card:hover {
328	    transform: translateY(-2px);
329	    box-shadow: 0 12px 40px hsl(var(--foreground) / 0.08);
330	  }
331	
332	  .ai-progress-bar {
333	    background: linear-gradient(90deg, hsl(var(--primary)), hsl(var(--momma-gradient-end)));
334	    height: 3px;
335	    border-radius: 2px;
336	    animation: ai-progress 2s ease-in-out infinite;
337	  }
338	
339	  @keyframes ai-progress {
340	    0%, 100% { opacity: 0.6; }
341	    50% { opacity: 1; }
342	  }
343	
344	  .ai-step-indicator {
345	    background: hsl(var(--muted));
346	    border: 2px solid hsl(var(--border));
347	    transition: all 0.3s ease;
348	  }
349	
350	  .ai-step-indicator.active {
351	    background: hsl(var(--primary));
352	    border-color: hsl(var(--primary));
353	    box-shadow: 0 0 0 3px hsl(var(--primary) / 0.2);
354	  }
355	
356	  .ai-step-indicator.completed {
357	    background: hsl(var(--success));
358	    border-color: hsl(var(--success));
359	  }
360	
361	  .floating-action {
362	    position: fixed;
363	    bottom: 2rem;
364	    right: 2rem;
365	    z-index: 50;
366	    border-radius: 50%;
367	    box-shadow: 0 8px 32px hsl(var(--foreground) / 0.12);
368	    transition: all 0.3s ease;
369	  }
370	
371	  .floating-action:hover {
372	    transform: scale(1.1);
373	    box-shadow: 0 12px 40px hsl(var(--foreground) / 0.2);
374	  }
375	}
