1	import { useState, useEffect } from "react";
2	import { Package, TrendingUp, AlertTriangle, Users } from "lucide-react";
3	import { StatCard } from "./StatCard";
4	import { supabase } from "@/integrations/supabase/client";
5	import { useRealtimeUpdates } from "@/features/dashboard/model/useRealtimeUpdates";
6	import { useStoreFilter } from "@/shared/hooks/useStoreData";
7	import { wideInfo, wideError } from "@/shared/lib/telemetry/wide-events";
8	import { withTrace } from "@/shared/lib/telemetry/tracer";
9	import { recordOperation, recordOperationDuration } from "@/shared/lib/telemetry/metrics";
10	import { useTelemetryAttrs } from "@/shared/lib/telemetry/useTelemetryAttrs";
11	
12	interface Stats {
13	  totalProdutos: number;
14	  totalMovimentacoes: number;
15	  alertasAtivos: number;
16	  usuariosAtivos: number;
17	}
18	
19	export function RealStatCards() {
20	  const { hasData, applyStoreFilter, selectedStore } = useStoreFilter();
21	  const [stats, setStats] = useState<Stats>({
22	    totalProdutos: 0,
23	    totalMovimentacoes: 0,
24	    alertasAtivos: 0,
25	    usuariosAtivos: 0,
26	  });
27	  const [isLoading, setIsLoading] = useState(true);
28	  const telemetryAttrs = useTelemetryAttrs();
29	
30	  useEffect(() => {
31	    fetchStats();
32	    // eslint-disable-next-line react-hooks/exhaustive-deps
33	  }, [selectedStore, hasData]);
34	
35	  // Real-time updates
36	  useRealtimeUpdates(() => {
37	    fetchStats();
38	  });
39	
40	  const fetchStats = async () => {
41	    // Se a loja não tem dados, retorna zeros
